<?php
declare(strict_types=1);namespace BizStock\Services;
use BizStock\Support\{AtomicWrite,ApiInput,CanonicalJson,ReadSnapshot};use BizStock\Repositories\{StockCountRepository,StockRepository,AuditRepository,OperationRepository};use BizStock\Http\{Authorization,HttpException};
final readonly class StockCountService
{
 public function __construct(private \PDO $pdo){}
 public function read(?int $id,array $query,string $role):array{Authorization::requireRole(['role'=>$role],['Admin','Staff']);return ReadSnapshot::run($this->pdo,function()use($id,$query){$repo=new StockCountRepository($this->pdo);if($id===null)return $repo->listing($query);$count=$repo->find($id);if(!$count)throw new HttpException(404,'NOT_FOUND','Count not found.');$count['lines']=$repo->lines($id);return ['data'=>$count,'meta'=>[]];});}
 private function locked(StockCountRepository $repo,int $id,array $body):array{$row=$repo->find($id,true);if(!$row)throw new HttpException(404,'NOT_FOUND','Count not found.');if($row['version']!==ApiInput::integer($body['expected_version']??null,'expected_version',1))throw new HttpException(409,'STALE_EDIT','This count changed. Reload and review; entries have not been silently rebased.');if($row['version']>=2147483647)throw new HttpException(409,'VERSION_OVERFLOW','Count revision limit reached.');return $row;}
 private function audit(array $actor,string $action,int $id,?array $before,array $after,string $request):void{(new AuditRepository($this->pdo))->record((int)$actor['user_id'],'stock_count.'.$action,'stock_count',$id,$before,$after,$request);}
 public function create(array $body,array $actor,string $key,string $request):array{
  if(array_diff(array_keys($body),['note']))throw new HttpException(422,'VALIDATION_ERROR','Supply note only.');$note=isset($body['note'])?ApiInput::text($body['note'],'note',500,false):null;$key=ApiInput::operationKey($key);$hash=hash('sha256',CanonicalJson::encode(['note'=>$note]));return AtomicWrite::run($this->pdo,$actor,['Admin','Staff'],function($current)use($note,$key,$hash,$request){$ops=new OperationRepository($this->pdo);$replay=$ops->reserve($current['user_id'],'stock_count.create',$key,$hash);if($replay!==null)return $replay;$repo=new StockCountRepository($this->pdo);$id=$repo->create($current['user_id'],$note);$result=$repo->find($id);$this->audit($current,'created',$id,null,$result,$request);return $ops->complete($current['user_id'],$key,null,null,$result);});
 }
 public function saveLine(int $id,int $product,array $body,array $actor,string $request):array{
  if(array_diff(array_keys($body),['expected_version','counted_quantity','reason','recount','expected_stock_revision']))throw new HttpException(422,'VALIDATION_ERROR','Unknown count-line field.');$quantity=ApiInput::integer($body['counted_quantity']??null,'counted_quantity');$reason=isset($body['reason'])?ApiInput::text($body['reason'],'reason',500,false):null;$recount=isset($body['recount'])?ApiInput::boolean($body['recount'],'recount'):false;
  return AtomicWrite::run($this->pdo,$actor,['Admin','Staff'],function($current)use($id,$product,$body,$quantity,$reason,$recount,$request){$repo=new StockCountRepository($this->pdo);$count=$this->locked($repo,$id,$body);if($count['status']!=='draft')throw new HttpException(409,'COUNT_STATE','Only draft counts accept entries. Return a submitted count to draft explicitly.');$lines=$repo->lines($id);$before=null;foreach($lines as $line)if($line['product_id']===$product)$before=$line;if(!$before&&count($lines)>=100)throw new HttpException(422,'VALIDATION_ERROR','A count is bounded to 100 product lines.');$row=(new StockRepository($this->pdo))->product($product);if(!$row||!$row['is_active'])throw new HttpException(409,'PRODUCT_ARCHIVED','Choose an active product.');if((!$before||$recount)&&$row['stock_revision']!==ApiInput::integer($body['expected_stock_revision']??null,'expected_stock_revision',1))throw new HttpException(409,'COUNT_STALE','Stock changed while entering the count. Refresh the product and explicitly recount.');$baseline=$before&&!$recount?$before:['product_id'=>$product,'sku_snapshot'=>$row['sku'],'product_name_snapshot'=>$row['product_name'],'unit_code'=>$row['unit_code'],'expected_quantity'=>$row['quantity'],'expected_revision'=>$row['stock_revision']];$line=$baseline+['reason'=>null];$line['counted_quantity']=$quantity;$line['reason']=$reason;$line['discrepancy']=$quantity-$line['expected_quantity'];if($quantity!==$line['expected_quantity']&&trim($reason??'')==='')throw new HttpException(422,'VALIDATION_ERROR','A reason is required for a nonzero discrepancy.');$repo->saveLine($id,$line);$repo->advance($id);$this->audit($current,$recount?'line_recounted':'line_saved',$id,$before,$line,$request);return $repo->find($id)+['lines'=>$repo->lines($id)];});
 }
 public function transition(int $id,string $action,array $body,array $actor,string $key,string $request):array{
  if(array_diff(array_keys($body),['expected_version']))throw new HttpException(422,'VALIDATION_ERROR','Supply expected_version only.');$roles=$action==='approve'?['Admin']:['Admin','Staff'];if(!in_array($action,['submit','approve','cancel','return_to_draft'],true))throw new HttpException(422,'VALIDATION_ERROR','Unknown count action.');$key=$action==='approve'?ApiInput::operationKey($key):$key;$hash=hash('sha256',CanonicalJson::encode(['count_id'=>$id,'action'=>$action,'expected_version'=>ApiInput::integer($body['expected_version']??null,'expected_version',1)]));
  return AtomicWrite::run($this->pdo,$actor,$roles,function($current)use($id,$action,$body,$key,$hash,$request){$repo=new StockCountRepository($this->pdo);$ops=new OperationRepository($this->pdo);if($action==='approve'){$replay=$ops->reserve($current['user_id'],'stock_count.approve',$key,$hash);if($replay!==null)return $replay;}$count=$this->locked($repo,$id,$body);$lines=$repo->lines($id);$status=$count['status'];$target=match($action){'submit'=>'submitted','approve'=>'approved','cancel'=>'cancelled','return_to_draft'=>'draft'};
   if(($action==='submit'&&($status!=='draft'||!$lines))||($action==='approve'&&$status!=='submitted')||($action==='cancel'&&!in_array($status,['draft','submitted'],true))||($action==='return_to_draft'&&$status!=='submitted'))throw new HttpException(409,'COUNT_STATE','This state transition is not available. Reload and review.');
   if($action==='approve'){
    // Rows are returned in ascending product ID. Validate ALL baselines before ANY append.
    $stock=new StockRepository($this->pdo);foreach($lines as $line){$product=$stock->product($line['product_id']);if(!$product||!$product['is_active']||$product['stock_revision']!==$line['expected_revision']||$product['unit_code']!==$line['unit_code']||$product['quantity']!==$line['expected_quantity'])throw new HttpException(409,'COUNT_STALE','Stock or eligibility changed. Return to draft and explicitly recount before approval.');}
    foreach($lines as $line){$difference=$line['counted_quantity']-$line['expected_quantity'];if($difference===0)continue;if(trim($line['reason']??'')==='')throw new HttpException(422,'VALIDATION_ERROR','Adjustment reason missing.');$movement=(new StockMovementService($this->pdo))->appendInTransaction(['product_id'=>$line['product_id'],'type'=>$difference>0?'IN':'OUT','quantity'=>abs($difference),'notes'=>'Physical count #'.$id.': '.$line['reason']],$current,'count:'.$id.':'.$line['product_id'].':'.hash('sha256',$key),$hash,'adjustment');$repo->link($id,$line['product_id'],$movement['transaction_id']);}
   }
   $repo->advance($id,$target,$action==='approve'?$current['user_id']:null);$result=$repo->find($id)+['lines'=>$repo->lines($id)];$this->audit($current,$action,$id,$count,$result,$request);return $action==='approve'?$ops->complete($current['user_id'],$key,null,null,$result):$result;
  });
 }
}
